package com.acme.operations.customer;

import jakarta.persistence.*;

// JPA maps rows from the database to instances of this entity.
@Entity
// Map the entity to the table managed by database migrations.
@Table(name = "customer")
// The customer's entity to which the orders belong; it is not the user who log in.
public class Customer {
    // Identify the primary key used by JPA.
    @Id
    // The database generates the ID on insert. JPA reads the generated value.
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    // Primary key generated by the base when inserting the customer.
    private Long id;

    // Map this field to a database column. The DTO and the database also validate input.
    @Column(nullable = false, length = 200)
    // Name also shown when you consult your orders.
    private String name;

    // Map this field to a database column. The DTO and the database also validate input.
    @Column(nullable = false, length = 32)
    // The customer's tax identifier, with one-time defined in the database.
    private String taxId;

    // Map this field to a database column. The DTO and the database also validate input.
    @Column(nullable = false, length = 254)
    // Contact mail; the format is valid in the input DTO.
    private String email;

    // Map this field to a database column. The DTO and the database also validate input.
    @Column(nullable = false, length = 500)
    // Customer contact address.
    private String address;

    // Map this field to a database column. The DTO and the database also validate input.
    @Column(nullable = false)
    // Set active=false to deactivate the record and preserve existing order relationships.
    private boolean active = true;

    // JPA checks and increments the version on update to detect concurrent changes.
    @Version private long version;

    // JPA uses the empty builder by rebuilding a row as an object.
    protected Customer() {}

    // It initiates the editable fields from the received DTO; it does not run an INSERT.
    public Customer(CustomerDtos.Input input) {
        // It reuses the applied standardization also when editing.
        update(input);
    }

    // It modifies contact data; id and version remain under persistence control.
    public void update(CustomerDtos.Input input) {
        // It eliminates outer spaces from the name.
        this.name = input.name().strip();
        // Norms the tax identifier to compare values consistently.
        this.taxId = input.taxId().strip().toUpperCase(java.util.Locale.ROOT);
        // Clean out outer spaces of the mail and address.
        this.email = input.email().strip();
        this.address = input.address().strip();
    }

    // Disable the customer by keeping your line and the orders that refer to it.
    public void deactivate() {
        // The managed entity shall keep the change when synchronized in the transaction.
        active = false;
    }

    // Return the current field value from the entity in memory.
    public Long getId() {
        // Return the current value.
        return id;
    }

    // Return the current field value from the entity in memory.
    public String getName() {
        // Return the current value.
        return name;
    }

    // Return the current field value from the entity in memory.
    public String getTaxId() {
        // Return the current value.
        return taxId;
    }

    // Return the current field value from the entity in memory.
    public String getEmail() {
        // Return the current value.
        return email;
    }

    // Return the current field value from the entity in memory.
    public String getAddress() {
        // Return the current value.
        return address;
    }

    // Return the current field value from the entity in memory.
    public boolean isActive() {
        // Return the current value.
        return active;
    }

    // Return the current field value from the entity in memory.
    public long getVersion() {
        // Return the current value.
        return version;
    }
}
